const raw = $input.first().json;
const payload = raw.body || raw;
const isEmptyPayload = !payload || Object.keys(payload).length === 0;

// Manual test runs have no payload - default to a sample keyword so the workflow is testable end to end
const triggerKeyword = payload.keyword || (isEmptyPayload ? 'best project management software' : null);
const triggerTargetDomain = payload.targetDomain || payload.domain || (isEmptyPayload ? 'example.com' : null);

return [{
  json: {
    triggerKeyword: triggerKeyword || null,
    triggerTargetDomain: triggerTargetDomain || null,
    results: [],
    processedCount: 0
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    queue: [{ keyword: item.triggerKeyword, targetDomain: item.triggerTargetDomain || '' }]
  }
}];

const state = $('If Ad Hoc Keyword Provided').first().json;
const response = $input.first().json;
const keywords = response.keywords || response.items || (Array.isArray(response) ? response : []);

const queue = keywords.map(k => ({
  keyword: k.keyword || k.query || String(k),
  targetDomain: k.targetDomain || k.domain || ''
}));

return [{
  json: {
    ...state,
    queue
  }
}];

const item = $input.first().json;
const queue = [...(item.queue || [])];
const next = queue.shift();

return [{
  json: {
    ...item,
    queue,
    currentKeyword: next ? next.keyword : null,
    currentTargetDomain: next ? next.targetDomain : null,
    hasNext: !!next
  }
}];

const state = $('Get Next Keyword from Queue').first().json;
const response = $input.first().json;

const rawResults = response.organic_results || response.results || response.items || [];

const results = rawResults.slice(0, 100).map((r, idx) => {
  const url = r.link || r.url || '';
  let domain = r.domain || '';
  if (!domain) {
    try { domain = new URL(url).host; } catch (e) { domain = ''; }
  }
  return {
    position: Number(r.position) || (idx + 1),
    domain,
    url,
    title: r.title || ''
  };
});

return [{
  json: {
    ...state,
    snapshotTakenAt: new Date().toISOString(),
    currentResults: results,
    currentResultCount: results.length
  }
}];

const state = $('Normalize SERP Snapshot').first().json;
const prevResponse = $input.first().json;

const previousResults = prevResponse.results || prevResponse.currentResults || (prevResponse.snapshot && prevResponse.snapshot.results) || [];

function bestByDomain(list) {
  const byDomain = {};
  for (const r of list) {
    if (!byDomain[r.domain] || r.position < byDomain[r.domain].position) byDomain[r.domain] = r;
  }
  return byDomain;
}

const currentByDomain = bestByDomain(state.currentResults);
const previousByDomain = bestByDomain(previousResults);
const allDomains = new Set([...Object.keys(currentByDomain), ...Object.keys(previousByDomain)]);

const movements = [];
for (const domain of allDomains) {
  if (!domain) continue;
  const curr = currentByDomain[domain];
  const prev = previousByDomain[domain];
  if (curr && prev) {
    movements.push({
      domain,
      currentPosition: curr.position,
      previousPosition: prev.position,
      positionChange: prev.position - curr.position,
      status: 'tracked',
      url: curr.url,
      title: curr.title
    });
  } else if (curr && !prev) {
    movements.push({ domain, currentPosition: curr.position, previousPosition: null, positionChange: null, status: 'new_entrant', url: curr.url, title: curr.title });
  } else if (!curr && prev) {
    movements.push({ domain, currentPosition: null, previousPosition: prev.position, positionChange: null, status: 'dropped_out', url: prev.url, title: prev.title });
  }
}

const bigMovers = movements.filter(m => m.positionChange !== null && Math.abs(m.positionChange) >= state.significantMovementThreshold);
const newEntrantsTopBand = movements.filter(m => m.status === 'new_entrant' && m.currentPosition <= state.topBandSize);
const dropoutsFromTopBand = movements.filter(m => m.status === 'dropped_out' && m.previousPosition <= state.topBandSize);
const targetDomainMovement = movements.find(m => m.domain === state.currentTargetDomain) || null;

return [{
  json: {
    ...state,
    previousResults,
    hasPreviousSnapshot: previousResults.length > 0,
    movements,
    bigMovers,
    newEntrantsTopBand,
    dropoutsFromTopBand,
    targetDomainMovement
  }
}];

const state = $('Detect SERP Movement').first().json;
const movements = state.movements || [];

const topWinners = movements
  .filter(m => (m.positionChange !== null && m.positionChange > 0) || m.status === 'new_entrant')
  .sort((a, b) => (b.positionChange ?? 100) - (a.positionChange ?? 100))
  .slice(0, 10);

const topLosers = movements
  .filter(m => (m.positionChange !== null && m.positionChange < 0) || m.status === 'dropped_out')
  .sort((a, b) => (a.positionChange ?? -100) - (b.positionChange ?? -100))
  .slice(0, 10);

return [{
  json: {
    ...state,
    topWinners,
    topLosers
  }
}];

const aiResponse = $input.first().json;
const state = $('Identify Winners and Losers').first().json;

let analysis;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch (e) {
  analysis = { winnerCharacteristics: '', loserCharacteristics: '', notableMoves: [], summary: 'Unable to parse AI response' };
}

return [{
  json: {
    ...state,
    winnersLosersAnalysis: analysis
  }
}];

const aiResponse = $input.first().json;
const state = $('Parse Winners/Losers Analysis').first().json;

let pattern;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  pattern = JSON.parse(cleaned);
} catch (e) {
  pattern = { patternType: 'unknown', confidence: 0, narrative: 'Unable to parse AI response', recommendedActions: [] };
}

const tdm = state.targetDomainMovement;
let targetDomainSignificantMove = false;
if (tdm) {
  if (tdm.positionChange !== null && Math.abs(tdm.positionChange) >= state.significantMovementThreshold) targetDomainSignificantMove = true;
  if (tdm.status === 'new_entrant' && tdm.currentPosition <= state.topBandSize) targetDomainSignificantMove = true;
  if (tdm.status === 'dropped_out' && tdm.previousPosition <= state.topBandSize) targetDomainSignificantMove = true;
}

const keywordReport = {
  keyword: state.currentKeyword,
  targetDomain: state.currentTargetDomain,
  snapshotTakenAt: state.snapshotTakenAt,
  targetDomainMovement: tdm,
  bigMoversCount: (state.bigMovers || []).length,
  newEntrantsTopBandCount: (state.newEntrantsTopBand || []).length,
  dropoutsFromTopBandCount: (state.dropoutsFromTopBand || []).length,
  winnersLosersAnalysis: state.winnersLosersAnalysis,
  pattern
};

return [{
  json: {
    ...state,
    pattern,
    targetDomainSignificantMove,
    results: [...(state.results || []), keywordReport],
    processedCount: (state.processedCount || 0) + 1
  }
}];

