const item = $input.first().json;
const results = item.results || [];

const keywordsWithSignificantMovement = results.filter(r =>
  (r.bigMoversCount || 0) > 0 || (r.newEntrantsTopBandCount || 0) > 0 || (r.dropoutsFromTopBandCount || 0) > 0
).length;

const patternCounts = {};
for (const r of results) {
  const p = r.pattern && r.pattern.patternType;
  if (p) patternCounts[p] = (patternCounts[p] || 0) + 1;
}
const topPatterns = Object.entries(patternCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([patternType, count]) => ({ patternType, count }));

return [{
  json: {
    whatsappBusinessPhoneId: item.whatsappBusinessPhoneId,
    whatsappRecipientPhone: item.whatsappRecipientPhone,
    keywordsTracked: results.length,
    keywordsWithSignificantMovement,
    topPatterns,
    keywordReports: results
  }
}];
